    @Test void fullDatasetPageIsIncompleteAndConservative() {StringBuilder b=new StringBuilder("[");for(int i=0;i<2;i++){if(i>0)b.append(',');b.append("{\"url\":\"https://www.instagram.com/reel/x\",\"text\":\"ok\"}");}b.append(']');var t=new TestTransport().reply(201,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"RUNNING\"}}").reply(200,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"SUCCEEDED\",\"buildNumber\":\"0.0.50\",\"buildId\":\"aJLRmMdQapLQRT4sJ\"}}").reply(200,b.toString());var c=new TranscriptClient(ClientConfig.builder().token("x").transport(t).datasetPageLimit(2).pollInterval(java.time.Duration.ZERO).sleeper(d->{}).build());var r=c.getTranscript(URL);assertFalse(r.datasetComplete());assertEquals(Status.UNKNOWN,r.status());}
