    @Test void diagnosticRedactionMatchesPythonCredentialPatternsAndBoundsText(){
        String input="password=fictional-pass apiKey: fake-one api_key=\"fake-two\" api-key='fake-three' Token: fake-token\nBearer fake.bearer.value";
        String clean=JsonSupport.safeError(input);
        for(String secret:List.of("fictional-pass","fake-one","fake-two","fake-three","fake-token","fake.bearer.value"))assertFalse(clean.contains(secret));
        assertTrue(clean.contains("password=[REDACTED]"));assertTrue(clean.contains("apiKey: [REDACTED]"));
        assertTrue(clean.contains("api_key=\"[REDACTED]"));assertTrue(clean.contains("api-key='[REDACTED]"));assertTrue(clean.contains("Bearer [REDACTED]"));
        assertFalse(clean.contains("\n"));assertEquals(300,JsonSupport.safeError("diagnostic "+"x".repeat(400)).length());
        assertEquals("crawed empty",JsonSupport.safeError("crawed empty"));
    }
    @Test void actorErrMsgIsSafeInPublicResultsWhileRawItemIsPreserved(){
        String raw="blocked password=fictional-value api_key=fake-key";
        var single=client(TestTransport.successful("[{\"url\":\"https://www.instagram.com/reel/AbC_12/\",\"errMsg\":"+JsonSupport.MAPPER.valueToTree(raw)+"}]")).getTranscript(URL);
        assertEquals(Status.ACTOR_ERROR,single.status());assertFalse(single.error().contains("fictional-value"));assertFalse(single.error().contains("fake-key"));
        var profile=client(TestTransport.successful("[{\"url\":\"https://www.instagram.com/p/post/\",\"ownerUsername\":\"alice\",\"type\":\"Video\",\"errMsg\":"+JsonSupport.MAPPER.valueToTree(raw)+"}]")).getProfilePosts("alice");
        assertEquals("actor_error",profile.posts().get(0).status());assertFalse(profile.posts().get(0).error().contains("fictional-value"));
        assertEquals(raw,profile.posts().get(0).raw().path("errMsg").asText());
    }
