    @Test void profileL3ShapePrioritizesActorErrorAndRetainsErrorAndRawItems(){
        StringBuilder items=new StringBuilder("[");
        for(int i=0;i<19;i++){if(i>0)items.append(',');items.append("{\"url\":\"https://www.instagram.com/reel/success-").append(i).append("/\",\"type\":\"Video\",\"ownerUsername\":\"lovepegz\"}");}
        items.append(",{\"inputUrl\":\"lovepegz\",\"ownerUsername\":\"greentee_golfshop\",\"url\":\"https://www.instagram.com/p/Dek3TcexuU7/\",\"type\":\"Video\",\"childPosts\":[]}")
            .append(",{\"inputUrl\":\"theownerswitch\",\"inputUserName\":\"theownerswitch\",\"errMsg\":\"crawed empty\",\"url\":\"\",\"ownerUsername\":\"\",\"type\":\"\",\"timestamp\":\"0\"}]");
        var t=TestTransport.successful(items.toString());var r=client(t).getProfilePosts(List.of("lovepegz","theownerswitch","anotheraccount"));
        assertEquals(ProfileStatus.ACTOR_ERROR,r.status());assertEquals(Status.SUCCESS,r.executionStatus());
        assertEquals("One or more Profile items contain a non-empty errMsg",r.error());assertEquals(21,r.posts().size());
        assertEquals(19L,r.posts().stream().filter(p->p.status().equals("success")).count());
        assertEquals(1L,r.posts().stream().filter(p->p.status().equals("unknown")).count());
        assertEquals(1L,r.posts().stream().filter(p->p.status().equals("actor_error")).count());
        assertEquals("Post owner is missing or does not match a requested account",r.posts().get(19).error());
        assertEquals("crawed empty",r.posts().get(20).error());assertEquals("crawed empty",r.posts().get(20).raw().path("errMsg").asText());
        assertEquals("lovepegz",r.posts().get(19).raw().path("inputUrl").asText());assertEquals("greentee_golfshop",r.posts().get(19).raw().path("ownerUsername").asText());
        assertEquals(r.posts().stream().map(ProfilePost::raw).toList(),r.rawItems());
    }
