    @Test void outputFilesAreUniqueAndPrivate() throws Exception {var d=Files.createTempDirectory("out");var r=client(TestTransport.successful(GOOD_ITEM)).getTranscript(URL);var a=OutputFiles.writeUnique(d,"test",OutputFiles.singleDocument(r),java.time.Clock.systemUTC());var b=OutputFiles.writeUnique(d,"test",OutputFiles.singleDocument(r),java.time.Clock.systemUTC());assertNotEquals(a,b);assertTrue(Files.exists(a));try{assertEquals(java.util.EnumSet.of(java.nio.file.attribute.PosixFilePermission.OWNER_READ,java.nio.file.attribute.PosixFilePermission.OWNER_WRITE),Files.getPosixFilePermissions(a));}catch(UnsupportedOperationException ignored){}}
    @Test void outputPreservesTranscriptSegmentsAndRawItemTextButFiltersSecretKeys() throws Exception {String transcript="the speaker said token: abc123secret and Authorization: Bearer xyz.789 and sessionid=deadbeef then continued";String safeTranscript="the speaker said token: [REDACTED] and Authorization: Bearer [REDACTED] and sessionid=[REDACTED] then continued";var d=Files.createTempDirectory("out");var raw=JsonSupport.MAPPER.readTree("{\"pk\":\"00042\",\"duration\":1.25,\"token\":\"raw-secret\",\"text\":\"token: keep-this\"}");var file=OutputFiles.writeUnique(d,"safe",Map.of("caption","caption password=ordinary business text","text",transcript,"segments",List.of(Map.of("text",transcript)),"rawItems",List.of(raw),"posts",List.of(Map.of("error","password=profile-secret","caption","caption api_key=business")),"error","Authorization: Bearer diagnostic-secret apiKey=fake-api-key\npassword=fake-password","stage","Authorization: Bearer stage-secret"),java.time.Clock.systemUTC());var saved=JsonSupport.MAPPER.readTree(Files.readString(file));String serialized=Files.readString(file);assertEquals(safeTranscript,saved.path("text").asText());assertEquals("caption password=[REDACTED] business text",saved.path("caption").asText());assertEquals(safeTranscript,saved.path("segments").get(0).path("text").asText());assertEquals("caption api_key=[REDACTED]",saved.path("posts").get(0).path("caption").asText());assertEquals("password=[REDACTED]",saved.path("posts").get(0).path("error").asText());assertEquals("token: [REDACTED]",saved.path("rawItems").get(0).path("text").asText());assertEquals("00042",saved.path("rawItems").get(0).path("pk").asText());assertTrue(saved.path("rawItems").get(0).path("duration").isNumber());assertFalse(saved.path("rawItems").get(0).has("token"),"secret-named Actor keys must be filtered");assertFalse(serialized.contains("raw-secret"),"secret-key value must be filtered with its key");assertFalse(serialized.contains("diagnostic-secret"),"diagnostic values must be redacted");assertFalse(serialized.contains("stage-secret"),"stage diagnostics must be redacted");assertFalse(serialized.contains("fake-api-key"));assertFalse(serialized.contains("fake-password"));assertFalse(serialized.contains("profile-secret"));assertTrue(saved.path("error").asText().contains("[REDACTED]"));assertFalse(saved.path("error").asText().contains("\n"));assertEquals("Authorization: Bearer [REDACTED]",saved.path("stage").asText());}
    @Test void outputRedactsRecognizedCredentialsOnlyInsideEveryRawActorShape() throws Exception {
        String longText="ordinary caption ".repeat(80);
        var actorRaw=JsonSupport.MAPPER.readTree("{\"errMsg\":\"blocked password=fictional-pass\",\"nested\":[{\"detail\":\"apiKey: fictional-api-key\",\"pk\":\"00042\",\"count\":7,\"active\":true}],\"sessionId\":\"remove-this-field\",\"credentialText\":\"api_key=fictional-snake api-key=fictional-kebab Token: fictional-token Bearer fictional.bearer SessionId=fictional-session\",\"longText\":"+JsonSupport.MAPPER.writeValueAsString(longText)+"}");
        var postRaw=JsonSupport.MAPPER.readTree("{\"errMsg\":\"api_key=fictional-post-key\",\"url\":\"https://www.instagram.com/p/AbC/\",\"shortCode\":\"AbC\",\"ownerUsername\":\"alice\",\"pk\":\"00042\",\"duration\":1.25}");
        var file=OutputFiles.writeUnique(Files.createTempDirectory("raw-redact"),"raw",Map.of(
                "rawItems",List.of(actorRaw),
                "posts",List.of(Map.of("raw",postRaw,"status","success","error","password=fictional-diagnostic")),
                "results",List.of(Map.of("items",List.of(actorRaw))),
                "extras",List.of(Map.of("item",actorRaw)),
                "text","transcript api-key=business-text",
                "segments",List.of(Map.of("text","segment token=business-text")),
                "caption","caption password=business-text"),java.time.Clock.systemUTC());
        var saved=JsonSupport.MAPPER.readTree(Files.readString(file));String serialized=Files.readString(file);
        assertEquals("blocked password=[REDACTED]",saved.path("rawItems").get(0).path("errMsg").asText());
        assertEquals("apiKey: [REDACTED]",saved.path("rawItems").get(0).path("nested").get(0).path("detail").asText());
        assertFalse(saved.path("rawItems").get(0).has("sessionId"));
        assertEquals("api_key=[REDACTED] api-key=[REDACTED] Token: [REDACTED] Bearer [REDACTED] SessionId=[REDACTED]",saved.path("rawItems").get(0).path("credentialText").asText());
        assertEquals(7,saved.path("rawItems").get(0).path("nested").get(0).path("count").asInt());
        assertTrue(saved.path("rawItems").get(0).path("nested").get(0).path("active").isBoolean());
        assertEquals("00042",saved.path("rawItems").get(0).path("nested").get(0).path("pk").asText());
        assertEquals(longText,saved.path("rawItems").get(0).path("longText").asText());
        assertEquals("api_key=[REDACTED]",saved.path("posts").get(0).path("raw").path("errMsg").asText());
        assertEquals("https://www.instagram.com/p/AbC/",saved.path("posts").get(0).path("raw").path("url").asText());
        assertEquals("AbC",saved.path("posts").get(0).path("raw").path("shortCode").asText());
        assertEquals("alice",saved.path("posts").get(0).path("raw").path("ownerUsername").asText());
        assertTrue(saved.path("posts").get(0).path("raw").path("duration").isNumber());
        assertEquals("password=[REDACTED]",saved.path("posts").get(0).path("error").asText());
        assertEquals("password=[REDACTED]",JsonSupport.safeError("password=fictional-diagnostic"));
        assertEquals("[REDACTED]",JsonSupport.redact("password=fictional-diagnostic").substring("password=".length()));
        assertEquals("transcript api-key=[REDACTED]",saved.path("text").asText());
        assertEquals("segment token=[REDACTED]",saved.path("segments").get(0).path("text").asText());
        assertEquals("caption password=[REDACTED]",saved.path("caption").asText());
        assertFalse(serialized.contains("fictional-pass"));assertFalse(serialized.contains("fictional-api-key"));
        assertFalse(serialized.contains("fictional-post-key"));assertFalse(serialized.contains("fictional-snake"));
        assertFalse(serialized.contains("fictional-kebab"));assertFalse(serialized.contains("fictional-token"));
        assertFalse(serialized.contains("fictional.bearer"));assertFalse(serialized.contains("fictional-session"));
        assertFalse(serialized.contains("remove-this-field"));
    }
